countCheckBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "countCheckBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "AssumptionsLab",
                name = "countCheck",
                version = c(1,0,0),
                options = options,
                results = countCheckResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Count and Rate Regression
#'
#' 
#' @param data .
#' @param dep .
#' @param covs .
#' @param factors .
#' @param exposure .
#' @param exposureScale .
#' @param family .
#' @param showPlots Uncheck for a text-only report.
#' @param dispShowPlots .
#' @param zeroShowPlots .
#' @param residShowPlots .
#' @param residSmoother .
#' @param linShowPlots .
#' @param linSmoother .
#' @param influenceShowPlots .
#' @param influenceLabelMode .
#' @param influenceShowThreshold .
#' @param showGuides Show the fixed explanations (introduction and
#'   interpretation guides).
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$intro} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$designGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$design} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$dispersionGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$dispersion} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$modelComparisonGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$modelComparison} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$dispersionInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$meanVariancePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$zerosGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$zeros} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$zerosInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$frequencyPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$residualsGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$residuals} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$residualsInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$residualPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$quantileResidualPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$linearityGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$linearity} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$linearityInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$linearityPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$multicollinearityGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$multicollinearity} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$multicollinearityInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$influenceGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$influence} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$influenceInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$influencePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$rateRatiosGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$rateRatios} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$rateRatiosInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$design$asDF}
#'
#' \code{as.data.frame(results$design)}
#'
#' @export
countCheck <- function(
    data,
    dep,
    covs = NULL,
    factors = NULL,
    exposure = NULL,
    exposureScale = "raw",
    family = "poisson",
    showPlots = TRUE,
    dispShowPlots = TRUE,
    zeroShowPlots = TRUE,
    residShowPlots = TRUE,
    residSmoother = TRUE,
    linShowPlots = TRUE,
    linSmoother = "loess",
    influenceShowPlots = TRUE,
    influenceLabelMode = "top5",
    influenceShowThreshold = TRUE,
    showGuides = TRUE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("countCheck requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(factors)) factors <- jmvcore::resolveQuo(jmvcore::enquo(factors))
    if ( ! missing(exposure)) exposure <- jmvcore::resolveQuo(jmvcore::enquo(exposure))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(factors), factors, NULL),
            `if`( ! missing(exposure), exposure, NULL))

    for (v in factors) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- countCheckOptions$new(
        dep = dep,
        covs = covs,
        factors = factors,
        exposure = exposure,
        exposureScale = exposureScale,
        family = family,
        showPlots = showPlots,
        dispShowPlots = dispShowPlots,
        zeroShowPlots = zeroShowPlots,
        residShowPlots = residShowPlots,
        residSmoother = residSmoother,
        linShowPlots = linShowPlots,
        linSmoother = linSmoother,
        influenceShowPlots = influenceShowPlots,
        influenceLabelMode = influenceLabelMode,
        influenceShowThreshold = influenceShowThreshold,
        showGuides = showGuides)

    analysis <- countCheckClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}
